files.src/parser.ts:
export function parse(row: string) {
  const cells = row.split(",");
  if (cells.length !== 3) throw new Error("three fields required");
  const [id, date, amountText] = cells;
  if (!id) throw new Error("id required");
  const amount = Number(amountText);
  if (!Number.isFinite(amount)) throw new Error("finite amount required");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error("date format");
  return { id, date, amount };
}

